import os, sys, glob
CFG = '/app/config'
HIST = '/app/config-history'
rev = int(sys.argv[1]); env = sys.argv[2]; host = sys.argv[3]; svc = sys.argv[4]
revs = sorted(int(os.path.basename(d)[1:]) for d in glob.glob(HIST + '/r*'))

def readfile(abspath):
    if abspath.startswith(CFG + '/'):
        rel = os.path.relpath(abspath, CFG)
        for r in revs:
            if r > rev:
                p = '%s/r%04d/prev/%s' % (HIST, r, rel)
                if os.path.exists(p):
                    return open(p).read()
    return open(abspath).read()

state = {}
trace = []

def process(path, is_service):
    section = None
    for ln, line in enumerate(readfile(path).splitlines(), 1):
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            section = line[1:-1].strip()
            continue
        if '=' not in line:
            continue
        k, v = [x.strip() for x in line.split('=', 1)]
        if k == 'include':
            if section is not None:
                continue
            v = v.replace('${env}', env).replace('${host}', host)
            process(os.path.normpath(os.path.join(os.path.dirname(path), v)), False)
            continue
        if section is not None and section != svc:
            continue
        state[k] = v
        trace.append((os.path.relpath(path, '/app'), ln, section, k, v))

process('/app/services/%s/service.conf' % svc, True)
for t in trace:
    if t[3] in ('port_base', 'port_offset', 'admin_port', 'enabled'):
        print(t)
print(state.get('port_base'), state.get('port_offset'), state.get('admin_port'), state.get('enabled'))

